SELECT r.patch_major,r.win,json_extract(r.raw_json,'$.build_id'),
 json_type(r.raw_json,'$.players[0].potions'),json_array_length(r.raw_json,'$.players[0].potions'),
 (SELECT json_group_array(CASE WHEN t.type='text' THEN t.value WHEN t.type='object' THEN json_extract(t.value,'$.id') ELSE NULL END) FROM json_each(r.raw_json,'$.players[0].potions') t),
 (SELECT json_group_array(json_object('act',CAST(a.key AS INTEGER)+1,'point',CAST(n.key AS INTEGER)+1,
 'stats_n',json_array_length(n.value,'$.player_stats'),'hp',json_extract(n.value,'$.player_stats[0].current_hp'),
 'gold',json_extract(n.value,'$.player_stats[0].current_gold'),'map_point_type',json_extract(n.value,'$.map_point_type'),
 'rooms',json((SELECT json_group_array(json_object('kind',json_extract(z.value,'$.room_type'),'id',json_extract(z.value,'$.model_id'))) FROM json_each(n.value,'$.rooms') z)),
 'ancient_choice',json_object('type',json_type(n.value,'$.player_stats[0].ancient_choice'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].ancient_choice'),'items',json((SELECT json_group_array(CASE WHEN e.type='object' THEN json_object('TextKey',json_extract(e.value,'$.TextKey'),'title',CASE WHEN json_type(e.value,'$.title')='object' THEN json_object('key',json_extract(e.value,'$.title.key'),'table',json_extract(e.value,'$.title.table')) ELSE json_extract(e.value,'$.title') END,'was_chosen',json_extract(e.value,'$.was_chosen')) ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].ancient_choice') e))),'bought_cards',json_object('type',json_type(n.value,'$.player_stats[0].bought_cards'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].bought_cards'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].bought_cards') e))),'bought_colorless',json_object('type',json_type(n.value,'$.player_stats[0].bought_colorless'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].bought_colorless'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].bought_colorless') e))),'bought_relics',json_object('type',json_type(n.value,'$.player_stats[0].bought_relics'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].bought_relics'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].bought_relics') e))),'bought_potions',json_object('type',json_type(n.value,'$.player_stats[0].bought_potions'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].bought_potions'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].bought_potions') e))),'cards_removed',json_object('type',json_type(n.value,'$.player_stats[0].cards_removed'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].cards_removed'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].cards_removed') e))),'event_choices',json_object('type',json_type(n.value,'$.player_stats[0].event_choices'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].event_choices'),'items',json((SELECT json_group_array(CASE WHEN e.type='object' THEN json_object('title',CASE WHEN json_type(e.value,'$.title')='object' THEN json_object('key',json_extract(e.value,'$.title.key'),'table',json_extract(e.value,'$.title.table')) ELSE json_extract(e.value,'$.title') END) ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].event_choices') e))),'potion_choices',json_object('type',json_type(n.value,'$.player_stats[0].potion_choices'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].potion_choices'),'items',json((SELECT json_group_array(CASE WHEN e.type='object' THEN json_object('choice',json_extract(e.value,'$.choice'),'was_picked',json_extract(e.value,'$.was_picked')) ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].potion_choices') e))),'potion_used',json_object('type',json_type(n.value,'$.player_stats[0].potion_used'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].potion_used'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].potion_used') e))),'potion_discarded',json_object('type',json_type(n.value,'$.player_stats[0].potion_discarded'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].potion_discarded'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].potion_discarded') e))),'rest_site_choices',json_object('type',json_type(n.value,'$.player_stats[0].rest_site_choices'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].rest_site_choices'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].rest_site_choices') e))),'upgraded_cards',json_object('type',json_type(n.value,'$.player_stats[0].upgraded_cards'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].upgraded_cards'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].upgraded_cards') e))),'cards_gained',json_object('type',json_type(n.value,'$.player_stats[0].cards_gained'),'raw_item_n',json_array_length(n.value,'$.player_stats[0].cards_gained'),'items',json((SELECT json_group_array(CASE WHEN e.type='text' THEN e.value WHEN e.type='object' THEN json_extract(e.value,'$.id') ELSE NULL END) FROM json_each(n.value,'$.player_stats[0].cards_gained') e))))) FROM json_each(r.raw_json,'$.map_point_history') a JOIN json_each(a.value) n)
 FROM runs r WHERE r.character='SILENT' AND r.ascension=10 AND r.n_players=1 AND r.is_valid=1 AND r.was_abandoned=0 AND r.has_modifiers=0 AND r.patch_major IN (?,?,?,?,?)
